class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super().__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size,
                                 stride=stride, padding=padding,
                                 dilation=dilation, bias=bias)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        N, C, H, W = x.shape
        kH, kW = self.kernel_size
        padH, padW = self.padding
        dilH, dilW = self.dilation
        strideH = strideW = self.stride

        H_out = (H + 2 * padH - dilH * (kH - 1) - 1) // strideH + 1
        W_out = (W + 2 * padW - dilW * (kW - 1) - 1) // strideW + 1

        x = x.contiguous()
        weight = self.conv2d.weight.contiguous()

        output = torch.empty((N, self.out_channels, H_out, W_out),
                              device=x.device, dtype=x.dtype)

        TILE_H = 8
        TILE_W = 32
        block_size = TILE_H * (TILE_W // 4)  # register-blocked: each thread computes 4 outputs along W
        tiles_h = (H_out + TILE_H - 1) // TILE_H
        tiles_w = (W_out + TILE_W - 1) // TILE_W
        grid_x = N * self.out_channels
        grid_y = tiles_h * tiles_w
        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=(grid_x, grid_y, 1),
            block=(block_size, 1, 1),
            arguments=[x, weight, output],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output
